const brandAssets={"logo":"assets/logo-lightman.png","heart":"assets/logo-lightman.png"};const brandLogo=new Image(),brandHeart=new Image();brandLogo.src=brandAssets.logo;brandHeart.src=brandAssets.heart;for(const img of [brandLogo,brandHeart])img.onload=()=>{if(window.viewerReady)visualFrame()};window.brandImages={logo:brandLogo,heart:brandHeart};
function paintScreen(surface,time,mapCanvas=visualMapCanvas,style=led){
 const {mesh,canvas,ctx,texture,material}=surface;const w=canvas.width,h=canvas.height;
 if(style.mode!=='manual'&&mesh.userData.source.profile){
  ctx.drawImage(mapCanvas,0,0,mapCanvas.width,mapCanvas.height,0,0,w,h);
 }else if(style.mode!=='manual'){
  ctx.fillStyle='#03050d';ctx.fillRect(0,0,w,h);ctx.save();
  // Project the same stage-wide image onto each panel, including the rotated diamond.
  const angle=2*Math.atan2(mesh.quaternion.z,mesh.quaternion.w);
  ctx.translate(w/2,h/2);ctx.scale(w/(mesh.scale.x*(1-2*mesh.quaternion.y**2)),-h/mesh.scale.y);ctx.rotate(-angle);ctx.translate(-mesh.position.x,-mesh.position.y);
  ctx.translate(-17,12);ctx.scale(34/mapCanvas.width,-12/mapCanvas.height);ctx.drawImage(mapCanvas,0,0);ctx.restore();
 }else drawVisual(ctx,w,h,time);
 const main=mesh.name==='Pantalla principal';const diamond=mesh.name==='Rombo central';
 if(style.screenTitle){const image=diamond?brandHeart:brandLogo;const branded=diamond||main||mesh.name==='Pantalla lateral alta';if(branded&&image.complete&&image.naturalWidth){ctx.save();ctx.translate(w/2,h/2);if(diamond)ctx.rotate(2*Math.atan2(mesh.quaternion.z,mesh.quaternion.w));const maxW=diamond?w*.66:main?w*.66:w*.88,maxH=diamond?h*.66:main?h*.78:h*.45;const fit=Math.min(maxW/image.naturalWidth,maxH/image.naturalHeight);ctx.drawImage(image,-image.naturalWidth*fit/2,-image.naturalHeight*fit/2,image.naturalWidth*fit,image.naturalHeight*fit);ctx.restore()}}
 material.color.setScalar(style.blackout?0:style.screenBrightness/100*musicalDynamics.screen*(.95+.05*showRhythm.kick));texture.needsUpdate=true;
}
function synchronizeParameters(){led.sync=led.mode==='shared';if(led.sync){led.barColorA=led.screenColorA;led.barColorB=led.screenColorB}if(led.mode!=='manual')led.barSpeed=led.screenSpeed}
// Native audio owns time; canvas animation is throttled separately from lights.
