  const cache=led.sectionFollow&&led.autoPlay&&section.kind==='chorus'&&elapsed>=0&&elapsed<chorusHitDuration&&chorusTextureCache?.key===cueCacheKey(section)&&chorusTextureCache.id===led.composition?chorusTextureCache:null;
  if(cache&&(!fromAnimation||textureRefreshPending||lastAppliedChorusCache!==cache.key)){installChorusTextureCache(cache);painted=true;cached=true;}
  else if(!fromAnimation||textureRefreshPending||(!(cache&&elapsed<.15)&&performance.now()-lastTextureDraw>=1000/24)){drawScreenTextures(musicalDynamics.visualTime,transitionProgress());painted=true;}
