  barUniforms.uFloor.value=led.tubeFloor/100;tubeHalos.forEach(m=>m.visible=led.halo);barUniforms.uSync.value=led.sync?1:0;barUniforms.uBlend.value=blend;
  barUniforms.uHit.value=musicalDynamics.hit;barUniforms.uTime.value=effectTime;barUniforms.uSpeed.value=led.barSpeed/100;barUniforms.uBrightness.value=led.blackout?0:led.barBrightness/100*Math.max(musicalDynamics.hit,musicalDynamics.tubes*(.94+.06*showRhythm.kick));barUniforms.uMode.value=barModes.indexOf(led.barEffect);barUniforms.uA.value.set(led.barColorA);barUniforms.uB.value.set(led.barColorB);
  const screenLevel=led.blackout?0:led.screenBrightness/100*musicalDynamics.screen*(.95+.05*showRhythm.kick);for(const surface of surfaces)surface.material.color.setScalar(screenLevel);
  updateFixtures(effectTime,blend);updateAudience(showRhythm.beats);
  const sampledAt=performance.now(),sampleAudioTime=musicTransport.source==='audio'?songAudio.currentTime:null;
  const current=songSections[sectionIndexAt(simTime)],cueTime=current.kind==='chorus'?current.start:null;
  const renderStart=performance.now();update();const renderedAt=performance.now();
  cueFrameTiming.push({sampledAt,sampleAudioTime,showTime:simTime,cueTime,cueDeltaMs:cueTime===null?null:(simTime-cueTime)*1000,hit:musicalDynamics.hit,composition:led.composition,painted,cached,renderStart,renderedAt,renderCPU:renderedAt-renderStart,frameCPU:renderedAt-frameStart});
  if(cueFrameTiming.length>240)cueFrameTiming.shift();
