  const colors=active?[led.screenColorA,led.screenColorB]:visualPalettes[button.dataset.visual];
  const previewKey=[button.dataset.visual,...colors].join('|');
  if(button.dataset.previewKey!==previewKey){const preview=button.querySelector('canvas');drawVisual(preview.getContext('2d'),preview.width,preview.height,1.2,button.dataset.visual,colors,{...led,screenSpeed:100});button.dataset.previewKey=previewKey;}
