for(const button of document.querySelectorAll('[data-visual]'))button.onclick=()=>{led.autoPlay=false;transition=null;queuedComposition=null;led.screenEffect=button.dataset.visual;[led.screenColorA,led.screenColorB]=visualPalettes[led.screenEffect];led.composition='';if(led.mode==='composed'){[led.barColorA,led.barColorB]=[led.screenColorB,led.screenColorA]}syncInputs();saveLocally();visualFrame()};
