for(const [id,key] of Object.entries(binding))document.getElementById(id).addEventListener('input',e=>{led[key]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;if(['barEffect','barColorA','barColorB','screenEffect','screenColorA','screenColorB','screenSpeed','barSpeed'].includes(key)){led.composition='';led.autoPlay=false;transition=null;queuedComposition=null;}if(key==='autoHold')nextAutoAt=simTime+led.autoHold;syncInputs();saveLocally();visualFrame()});
