function compositionTarget(id){const c=compositions[id];if(!c)return;led.mode='composed';led.composition=id;led.sync=false;led.screenEffect=c.visual;led.barEffect=c.tube;[led.screenColorA,led.screenColorB]=c.colors;[led.barColorA,led.barColorB]=c.tubeColors;led.screenSpeed=c.speed;led.barSpeed=c.speed;}
