 if(transition&&!immediate){queuedComposition=id;updateAutoUI();return;}
 const from={...led};compositionTarget(id);
 transition=immediate||!led.playing||!from.composition?null:{from,start:simTime,duration:Math.min(led.fadeDuration,led.autoHold*.6)};
