// The existing concert engine consumes this provider's playback clock.
// A local audio file can still be selected in the private editor.
const nativeTransport={limit:audioLimit,refresh:refreshAudioUI,clock:updateSongClock,finish:finishSong,setPlaying:setShowPlaying};
const featuredTrack={id:'XRRW0DbJS_I',duration:216,title:'Historia de Amor · Caribeños de Guadalupe'};
let providerSeek=null;
let providerLoad;
let providerPendingPlay=false;
let providerInitTimer;

function providerTime(){return Number(musicTransport.player?.getCurrentTime?.())||0}
function providerDuration(){return Number(musicTransport.player?.getDuration?.())||featuredTrack.duration}
function providerStatus(text){document.getElementById('concert-music-status').textContent=text}
function providerUI(){
 if(musicTransport.source==='audio'){nativeTransport.refresh();return}
 const m=musicTransport;
 const big=document.getElementById('show-start');
 big.disabled=false;
 document.getElementById('show-start-label').textContent=m.loading?'CARGANDO CANCIÓN…':simTime>.15?'CONTINUAR SHOW':'INICIAR SHOW';
 audioPlay.disabled=false;
 document.getElementById('audio-restart').disabled=false;
 audioSeek.disabled=false;
 audioSeek.max=String(providerDuration());
 if(document.activeElement!==audioSeek)audioSeek.value=String(simTime);
 document.getElementById('audio-time').textContent=clockLabel(simTime)+' / '+clockLabel(providerDuration());
 document.getElementById('audio-volume-value').value=document.getElementById('audio-volume').value+'%';
}
function providerSample(force=false){
 const m=musicTransport;
 if(!m.ready)return;
 const value=providerTime();
 if(providerSeek&&Math.abs(value-providerSeek.target)>.7&&performance.now()<providerSeek.until)return;
 providerSeek=null;
 if(force||Math.abs(value-simTime)>.6)resetSongCue(value);
 else simTime=value;
 m.clipEnd=providerDuration();
 providerUI();
}
function providerSeekTo(time){
 const target=Math.min(providerDuration(),Math.max(0,time));
 resetSongCue(target);
 providerSeek={target,until:performance.now()+2500};
 if(musicTransport.ready)musicTransport.player.seekTo(target,true);
 providerUI();visualFrame();
}
function providerState(event){
 const m=musicTransport;
 if(m.source!=='youtube'){if(event.data===1)event.target.pauseVideo();return}
 m.player=event.target;
 if(event.data===1){
  m.active=true;m.running=true;m.ended=false;m.loading=false;
  providerPendingPlay=false;
  led.blackout=false;led.playing=true;
  providerSample();
  providerStatus('Historia de Amor · Caribeños de Guadalupe');
 }else if(event.data===2){
  m.running=false;led.playing=false;
  providerSample();
 }else if(event.data===3){
  m.running=false;led.playing=false;
  providerStatus('Cargando canción…');
 }else if(event.data===0){
  if(led.songLoop){
   m.loopCount++;m.ended=false;
   resetSongCue(0);providerSeek={target:0,until:performance.now()+2500};
   m.player.seekTo(0,true);m.player.playVideo();
  }else{
   m.running=false;m.ended=true;led.playing=false;resetSongCue(providerDuration());
  }
 }
 controls();providerUI();visualFrame();
}
function requestProviderPlay(){
 const m=musicTransport;
 if(!m.ready||m.source!=='youtube'||!providerPendingPlay)return;
 providerPendingPlay=false;
 const wrap=document.getElementById('music-player-wrap');
 const box=wrap.getBoundingClientRect();
 const visible=Math.min(innerHeight,box.bottom)-Math.max(0,box.top);
 if(visible<=box.height/2){providerStatus('Pulsa ▶ en el video para iniciar la canción.');return}
 if(m.ended||simTime>=providerDuration()-.2)providerSeekTo(0);
 else if(Math.abs(simTime-providerTime())>.3)providerSeekTo(simTime);
 m.player.setVolume(Number(document.getElementById('audio-volume').value));
 m.player.playVideo();
}
function loadProvider(){
 if(providerLoad)return providerLoad;
 providerLoad=new Promise((resolve,reject)=>{
  const create=()=>{
   const iframe=document.createElement('iframe');
   const url=new URL('https://www.youtube.com/embed/'+featuredTrack.id);
   url.searchParams.set('enablejsapi','1');url.searchParams.set('playsinline','1');
   if(location.protocol.startsWith('http'))url.searchParams.set('origin',location.origin);
   iframe.src=url.href;iframe.title=featuredTrack.title+' · YouTube';
   iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';
   iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';
   document.getElementById('music-player').replaceChildren(iframe);
   musicTransport.player=new YT.Player(iframe,{events:{
    onReady(event){
     clearTimeout(providerInitTimer);
     const m=musicTransport;m.player=event.target;m.ready=true;m.loading=false;
     providerUI();resolve(m.player);requestProviderPlay();
    },
    onStateChange:providerState,
    onAutoplayBlocked(){providerStatus('Pulsa ▶ dentro del video para iniciar la canción.');},
    onError(){
     musicTransport.running=false;led.playing=false;
     providerStatus('La canción no pudo reproducirse aquí. Puedes abrir el enlace oficial.');
     controls();providerUI();
    }
   }});
  };
  if(window.YT?.Player){create();return}
  window.onYouTubeIframeAPIReady=create;
  const api=document.createElement('script');api.src='https://www.youtube.com/iframe_api';
  api.onerror=()=>reject(new Error('YouTube unavailable'));
  document.head.append(api);
  providerInitTimer=setTimeout(()=>reject(new Error('YouTube timeout')),15000);
 }).catch(()=>{
  clearTimeout(providerInitTimer);
  providerLoad=null;musicTransport.loading=false;musicTransport.running=false;led.playing=false;
  providerStatus('No se pudo conectar con YouTube. Puedes abrir la canción oficial.');
  controls();providerUI();
 });
 return providerLoad;
}
function startCaribenos(){
 const m=musicTransport;
 m.source='youtube';songAudio.pause();m.active=true;m.loading=!m.ready;
 m.running=false;providerPendingPlay=true;
 const wrap=document.getElementById('music-player-wrap');wrap.hidden=false;
 if(!m.ready){providerStatus('Cargando la canción oficial…');wrap.scrollIntoView({block:'nearest',behavior:'instant'});}
 providerUI();
 if(m.ready)requestProviderPlay();else loadProvider();
}
// Preserve native playback for a file explicitly selected in the editor.
audioLimit=function(){return musicTransport.source==='audio'?nativeTransport.limit():providerDuration()};
refreshAudioUI=providerUI;
updateSongClock=function(now){
 if(musicTransport.source==='audio'){nativeTransport.clock(now);return}
 if(musicTransport.ready&&musicTransport.running&&led.playing)providerSample();
};
setShowPlaying=function(playing){
 const m=musicTransport;
 if(m.source==='audio'&&songAudio.src){nativeTransport.setPlaying(playing);return}
 if(playing){startCaribenos();return}
 providerPendingPlay=false;m.running=false;led.playing=false;
 if(m.ready)m.player.pauseVideo();
 controls();providerUI();visualFrame();
};
finishSong=function(){
 if(musicTransport.source==='audio'){nativeTransport.finish();return}
 if(led.songLoop){providerSeekTo(0);musicTransport.loopCount++;musicTransport.player?.playVideo();}
 else setShowPlaying(false);
};
playSongIntro=startCaribenos;
songState=providerState;
songUnavailable=function(text){musicTransport.running=false;led.playing=false;providerStatus(text);controls();providerUI()};
document.getElementById('show-start').onclick=()=>setShowPlaying(true);
document.getElementById('music-start').onclick=startCaribenos;
audioPlay.onclick=()=>setShowPlaying(!led.playing);
audioSeek.oninput=event=>{
 if(musicTransport.source==='audio'){
  songAudio.currentTime=Math.min(Number(event.target.value),audioLimit());
  musicTransport.lastAudioTime=songAudio.currentTime;resetSongCue(songAudio.currentTime);
  nativeTransport.refresh();visualFrame();
 }else providerSeekTo(Number(event.target.value));
};
document.getElementById('audio-restart').onclick=()=>{
 const resume=led.playing;
 if(musicTransport.source==='audio'){
  songAudio.currentTime=0;musicTransport.lastAudioTime=0;resetSongCue(0);
 }else{providerSeekTo(0);if(!resume&&musicTransport.ready)musicTransport.player.pauseVideo();}
 providerUI();visualFrame();
};
document.getElementById('audio-volume').oninput=event=>{
 songAudio.volume=Number(event.target.value)/100;
 if(musicTransport.ready)musicTransport.player.setVolume(Number(event.target.value));
 document.getElementById('audio-volume-value').value=event.target.value+'%';
};
document.getElementById('concert-local-audio')?.addEventListener('click',()=>document.getElementById('audio-file').click());
window.addEventListener('pagehide',()=>{songAudio.pause();if(musicTransport.ready)musicTransport.player.pauseVideo();});
window.showMusic.play=startCaribenos;window.showMusic.pause=()=>setShowPlaying(false);window.showMusic.resume=()=>setShowPlaying(true);window.showMusic.tick=updateSongClock;window.showMusic.stateChange=providerState;
musicTransport.source='youtube';musicTransport.clipEnd=featuredTrack.duration;
led.showBpm=133;led.beatOffset=0;led.blackout=true;led.playing=false;led.screenTitle=false;
resetSongCue(0);controls();providerUI();visualFrame();
// Keep mouse, keyboard and two-finger navigation available in the concert view.
const concertPointers=new Map();
host.tabIndex=0;
const markFreeView=()=>document.querySelectorAll('[data-view]').forEach(button=>button.classList.remove('active'));
renderer.domElement.onpointerdown=event=>{
 if(event.button!==0)return;
 concertPointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
 renderer.domElement.setPointerCapture(event.pointerId);
};
const pointerDistance=()=>{const [a,b]=concertPointers.values();return Math.hypot(a.x-b.x,a.y-b.y)};
renderer.domElement.onpointermove=event=>{
 const prior=concertPointers.get(event.pointerId);
 if(!prior)return;
 const oldDistance=concertPointers.size===2?pointerDistance():0;
 concertPointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
 if(oldDistance>5){dist=THREE.MathUtils.clamp(dist*oldDistance/Math.max(5,pointerDistance()),18,100);zoom=dist/fittedDistance();}
 else if(concertPointers.size===1){yaw-=(event.clientX-prior.x)*.005;pitch=THREE.MathUtils.clamp(pitch+(event.clientY-prior.y)*.004,-.05,1.5);}
 markFreeView();update();
};
for(const name of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(name,event=>concertPointers.delete(event.pointerId));
host.addEventListener('keydown',event=>{
 const motion={ArrowLeft:[.1,0],ArrowRight:[-.1,0],ArrowUp:[0,.07],ArrowDown:[0,-.07]}[event.key];
 if(motion){yaw+=motion[0];pitch=THREE.MathUtils.clamp(pitch+motion[1],-.05,1.5);}
 else if(['+','=','-'].includes(event.key)){dist=THREE.MathUtils.clamp(dist*(event.key==='-'?1.1:.9),18,100);zoom=dist/fittedDistance();}
 else return;
 event.preventDefault();markFreeView();update();
});

